Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Local Ltac norm_regset ::=
  repeat match goal with
  | |- context [@bvmap_set 5 word ?r ?v ?R] =>
      lazymatch R with TNode _ _ _ => idtac | TEmpty => idtac end;
      let p := eval vm_compute in (bv_key r) in
      change (@bvmap_set 5 word r v R) with (tset p v R);
      cbv beta iota delta [tset mkR]
  end.

(* [comment removed for export] *)
Definition kinv_inner_exit (ra sp gp tp t0 s0 s1 a0 a1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (rd sx : Z) : machine_state -> Prop :=
  fun ms' => exists (t1' t2' a2' a3' t3' t4' t5' : word) (F' : bvmap 5 word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1' t2' s0 s1 a0 a1 a2' a3' a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6)
             F' (Z_to_bv 64 0xc168c) fc None m' (seg_rom asegs)
    /\ fs_agree F F' /\ munch [(rd, rd + 4 * sx)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma kinv_inner : forall (k : nat) (j : Z)
    (ra sp gp tp t0 s0 s1 a0 a1 a4 a5 a6 a7 s2 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6 : word) F fc (m : mem) (rs rd sx : Z),
  Z.of_nat k = sx - j -> 0 <= j -> (1 <= k)%nat -> 0 < sx <= 20000 ->
  0 < rs -> rs mod 16 = 0 -> rs + 4 * sx <= 2^47 -> (rs + 4 * sx <= 0x7fff7000 \/ 0x10007fff8000 <= rs) ->
  0 < rd -> rd mod 16 = 0 -> rd + 4 * sx <= 2^47 -> (rd + 4 * sx <= 0x7fff7000 \/ 0x10007fff8000 <= rd) ->
  (rs + 4 * sx <= rd \/ rd + 4 * sx <= rs) ->
  wr_at asegs m rs (4 * sx) -> acc asegs m rs (4 * sx) -> wr_at asegs m rd (4 * sx) -> acc asegs m rd (4 * sx) -> mem_inv asegs m ->
  evt asegs (kinv_inner_exit ra sp gp tp t0 s0 s1 a0 a1 a4 a5 a6 a7 s2 (Z_to_bv 64 2147450880) s4 s5 s6 s7 s8 s9 s10 s11 t6 F fc m rd sx)
    (MS (mkR ra sp gp tp t0 (Z_to_bv 64 (rd + 4 * j)) (Z_to_bv 64 (rs + 4 * (sx - 1 - j))) s0 s1 a0 a1
             (Z_to_bv 64 (rs + 4 * (sx - 1 - j))) (Z_to_bv 64 (rd + 4 * j)) a4 a5 a6 a7 s2 (Z_to_bv 64 2147450880)
             s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 (sx - j)) t4 t5 t6)
